package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal      // PIC S9(3)V99 len=5 = 0
var WsFreeze int64           // PIC 99 len=2 = 0
var WsCount int64            // PIC 99 len=2 = 0
var WsFEd string             // PIC ZZ9.9 len=5
var WsCEd string             // PIC -ZZ9.99 len=7
var TempRecG TempRec

var tempFileLines []string
var tempFileIdx int
var inputDone bool

func formatPIC99(v int64) string {
	mod := int64(100)
	x := v % mod
	if x < 0 {
		x += mod
	}
	return fmt.Sprintf("%02d", x)
}

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.New(0, 0)
	}
	// s should contain only digits; ignore spaces inside
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return decimal.New(0, 0)
	}
	// allow sign?
	neg := false
	if len(t) > 0 && (t[0] == '-' || t[0] == '+') {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
	}
	if t == "" {
		return decimal.New(0, 0)
	}
	// parse integer
	n := int64(0)
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	d := decimal.New(n, -scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func storeS9_3V99(d decimal.Decimal) decimal.Decimal {
	// d is already rounded to 2 decimals
	// keep low-order digits: modulus 10^(3+2)=100000 on scaled value
	modulus := decimal.New(1, 5) // 10^5
	scaled := d.Shift(2)         // *100
	// ensure scaled is integer (truncate just in case)
	// use Truncate to remove any residual fractional due to decimal artefacts
	scaled = scaled.Truncate(0)
	abs := scaled.Abs()
	m := abs.Mod(modulus)
	if m.IsZero() {
		return decimal.New(0, 0)
	}
	if scaled.Sign() < 0 {
		return m.Neg().Shift(-2)
	}
	return m.Shift(-2)
}

func formatZZ9_9(d decimal.Decimal) string {
	// PIC ZZ9.9 => intDigits=3 scale=1 modulus 10^4
	scale := int32(1)
	intDigits := 3
	modPower := int32(intDigits) + scale // 4
	modulus := decimal.New(1, modPower)
	scaled := d.Abs().Shift(scale).Truncate(0)
	absScaled := scaled.Abs()
	modScaled := absScaled.Mod(modulus)
	// integer part and frac
	powScale := decimal.New(1, scale) // 10
	intPartDec := modScaled.Div(powScale).Truncate(0)
	fracPartDec := modScaled.Mod(powScale)

	intPart := intPartDec.IntPart()   // 0..999
	fracPart := fracPartDec.IntPart() // 0..9

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	// Z suppression for first ZCount = intDigits-1 =2
	zCount := intDigits - 1
	chars := []rune(intStr)
	suppress := true
	for i := 0; i < zCount; i++ {
		if suppress && chars[i] == '0' {
			// look ahead: if all remaining int digits are zero we keep last mandatory?
			// For Z positions we replace with space regardless; the final 9 will stay 0
			chars[i] = ' '
		} else {
			suppress = false
		}
		// if we encountered non-zero, stop suppressing
		if chars[i] != ' ' {
			suppress = false
		}
	}
	// If a Z position was not suppressed because earlier non-zero, keep it
	// The above loop already handles
	intFormatted := string(chars)
	fracStr := fmt.Sprintf("%0*d", scale, fracPart)
	return intFormatted + "." + fracStr
}

func formatMinusZZ9_99(d decimal.Decimal) string {
	scale := int32(2)
	intDigits := 3
	modPower := int32(intDigits) + scale //5
	modulus := decimal.New(1, modPower)
	abs := d.Abs()
	scaled := abs.Shift(scale).Truncate(0)
	modScaled := scaled.Mod(modulus)

	powScale := decimal.New(1, scale) //100
	intPartDec := modScaled.Div(powScale).Truncate(0)
	fracPartDec := modScaled.Mod(powScale)

	intPart := intPartDec.IntPart()
	fracPart := fracPartDec.IntPart()

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	zCount := intDigits - 1
	chars := []rune(intStr)
	suppress := true
	for i := 0; i < zCount; i++ {
		if suppress && chars[i] == '0' {
			chars[i] = ' '
		} else {
			suppress = false
		}
		if chars[i] != ' ' {
			suppress = false
		}
	}
	intFormatted := string(chars)
	fracStr := fmt.Sprintf("%0*d", scale, fracPart)

	signChar := ' '
	if d.Sign() < 0 && !d.IsZero() {
		// need to check if stored value is non-zero; if zero, sign is positive
		// For -0.00 after rounding/store we get zero, should be positive
		signChar = '-'
	}
	return string(signChar) + intFormatted + "." + fracStr
}

func READ_PARA() {
	if tempFileIdx >= len(tempFileLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := tempFileLines[tempFileIdx]
	tempFileIdx++
	// pad to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	TempRecG.TcSensor = line[0:4]
	s := line[4:8]
	TempRecG.TcF = parseImpliedDecimal(s, 1)
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	tmp := TempRecG.TcF.Sub(decimal.New(32, 0)).Mul(decimal.New(5, 0)).Div(decimal.New(9, 0))
	rounded := tmp.Round(2)
	WsC = storeS9_3V99(rounded)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(TempRecG.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", TempRecG.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		tempFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// need to preserve trailing spaces: Scanner strips \r\n but keeps other spaces
		// However Scanner may strip trailing spaces? It returns line without newline,
		// but keeps spaces. Use custom split to keep spaces.
		// We'll read raw bytes instead for safety.
		f.Close()
		data, err2 := os.ReadFile("input.dat")
		if err2 != nil {
			tempFileLines = []string{}
		} else {
			// split on \n
			raw := string(data)
			// normalize \r\n -> \n
			raw = strings.ReplaceAll(raw, "\r\n", "\n")
			raw = strings.ReplaceAll(raw, "\r", "\n")
			if raw == "" {
				tempFileLines = []string{}
			} else {
				parts := strings.Split(raw, "\n")
				// If file ends with newline, last part is empty trailing line -> should not be a record
				if len(parts) > 0 && parts[len(parts)-1] == "" {
					parts = parts[:len(parts)-1]
				}
				tempFileLines = parts
			}
		}
		_ = scanner
	}
	WsEofFlag = "N"
	inputDone = false
	WsC = decimal.New(0, 0)
	WsFreeze = 0
	WsCount = 0

	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE TEMP-FILE (no action)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func main() {
	MAIN_PARA()
}
